import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for any subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
    expect(policy.computeDiscountCents(1)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("throws for invalid percent values", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts boundary values 0 and 100", () => {
    expect(new PercentageDiscountPolicy(0).computeDiscountCents(1000)).toBe(0);
    expect(new PercentageDiscountPolicy(100).computeDiscountCents(1000)).toBe(1000);
  });

  it("computes discount rounded down", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(1000)).toBe(100);
    expect(policy.computeDiscountCents(1001)).toBe(100); // floor(100.1) = 100
    expect(policy.computeDiscountCents(1099)).toBe(109); // floor(109.9) = 109
  });

  it("returns 0 for zero or negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("throws for invalid amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new FixedAmountDiscountPolicy(1.5)).toThrow(RangeError);
  });

  it("returns discount up to subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
    expect(policy.computeDiscountCents(300)).toBe(300); // capped at subtotal
  });

  it("returns 0 for zero or negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("returns 0 for 0 amountCents", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(1000)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws if no policies provided", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(policy.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100, remaining 900; 10% of 900 = 90 => total 190
      expect(policy.computeDiscountCents(1000)).toBe(190);
    });

    it("does not exceed remaining subtotal in each step", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // first: min(800, 1000) = 800, remaining 200; second: min(800, 200) = 200
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const policy = new CompositeDiscountPolicy([
