    { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 500 }, quantity: 2 },
  ];

  it("updates prices from fetcher", async () => {
