describe("WeightBasedShippingCalculator", () => {
  it("throws if no brackets provided", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("throws for invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("throws for invalid overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 500 }], -1),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 500 }], 1.5),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 2)], 200)).toBe(0);
  });

  it("selects correct bracket based on total weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 200g * 2 = 400g → bracket 500g
    expect(calc.computeShippingCents([makeLine("a", 100, 2, 200)], 200)).toBe(300);
    // 500g * 1 = 500g → bracket 500g (exact boundary)
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 500)], 100)).toBe(300);
    // 600g → bracket 1000g
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 600)], 100)).toBe(600);
    // 4000g → bracket 5000g
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 4000)], 100)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 1000, costCents: 500 }],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 2000)], 100)).toBe(2000);
  });

  it("uses heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 5000)], 100)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 800 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 400)], 100)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 700)], 100)).toBe(600);
    expect(calc.computeShippingCents([makeLine("a", 100, 1, 1500)], 100)).toBe(800);
  });
});

