import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  price: number,
  qty: number,
  weight?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: price, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("throws for invalid flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    expect(() => new FlatShippingCalculator(1.5)).toThrow(RangeError);
  });

  it("throws for invalid freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    expect(() => new FlatShippingCalculator(500, 1.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when subtotal >= freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a", 5001, 1)], 5001)).toBe(0);
  });

  it("returns flat fee when subtotal < freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 4999, 1)], 4999)).toBe(599);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("throws if no brackets provided", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("throws for invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

