import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add()", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("increments quantity for existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("a", 100), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
      expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove()", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for non-existent product", () => {
      const cart = new Cart();
      expect(cart.remove("x")).toBe(false);
    });
  });

  describe("updateQuantity()", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is 0", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for non-existent product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow();
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear()", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot()", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const snap = cart.snapshot();
      snap[0].quantity = 99;
      snap[0].product.unitPriceCents = 999;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(200);
    });
  });

  describe("totals() with injected seams", () => {
    it("uses default seams (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(2000);
    });

    it("applies discount policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(500);
      expect(t.totalCents).toBe(1500);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    });

    it("clamps discount to subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });

    it("applies tax calculator on discounted subtotal", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(150),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(product("a", 1000), 1);
      const t = cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(t.taxCents).toBe(150);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("applies shipping calculator", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product("a", 1000), 1);
      const t = cart.totals();
      expect(t.shippingCents).toBe(799);
      expect(t.totalCents).toBe(1000 + 799);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("defaults region to US", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product("a", 100), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(100, "US");
    });
  });

  describe("checkout()", () => {
    it("returns totals and lines for basic checkout", async () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.id).toBe("a");
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      const priceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(999);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("checks inventory and throws InventoryError on denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 5);
      const inventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      await expect(cart.checkout({ inventoryChecker })).rejects.toMatchObject({
        productId: "a",
        requested: 5,
        available: 2,
      });
    });

    it("throws InventoryError when availableQuantity < requested", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 5);
      const inventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("passes inventory check when available", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const inventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(200);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "FR" });
      cart.add(product("a", 1000), 1);
      const asyncTaxProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(200);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });

    it("uses all collaborators together", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({ discountPolicy, region: "US" });
      cart.add(product("a", 500), 2);

      const priceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const inventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
      // prices refreshed: 600 * 2 = 1200 subtotal
      expect(result.totals.subtotalCents).toBe(1200);
      // discount is 100 (clamped) → discounted = 1100
      expect(result.totals.discountCents).toBe(100);
      // tax: floor(1100 * 0.1) = 110
      expect(result.totals.taxCents).toBe(110);
    });

    it("generates default reason when reason is undefined", async () => {
      const cart = new Cart();
      cart.add(product("x", 100), 10);
      const inventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e: any) {
        expect(e.message).toContain("insufficient stock");
        expect(e.message).toContain("x");
      }
    });
  });
});

